import java.io.*;
import java.nio.charset.StandardCharsets;

/** Server-owned startup screen. No HTML, JS or CSS is placed in the app web folder. */
final class StartupPage {
 static byte[] html(){return PAGE.getBytes(StandardCharsets.UTF_8);}
 static byte[] logo()throws IOException{
  try(InputStream in=StartupPage.class.getResourceAsStream("/noon-startup/logo.png")){
   if(in==null)throw new IOException("Startup logo resource missing; rebuild NoonJava.dll");
   return in.readAllBytes();
  }
 }
 private static final String PAGE = """
<!doctype html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Noon — نون</title>
<style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Tahoma,"Segoe UI",Arial,sans-serif}body{color:#263c36;background:#f6f4ed;background:radial-gradient(ellipse at 50% 0,#ede6d2 0,#f8f7f2 65%);padding:38px 18px}button{font:inherit;cursor:pointer}button:focus{outline:3px solid #c2a35a;outline-offset:4px}button:disabled{cursor:wait;opacity:.6}.shell{max-width:650px;margin:0 auto;text-align:center}.logo{width:112px;height:112px;object-fit:contain}.brand{margin:14px 0 6px;font-size:30px;letter-spacing:1px}.eyebrow{font-size:12px;color:#856b33;letter-spacing:2px;margin:0 0 25px}.card{position:relative;background:#fff;border:1px solid #e5e3da;border-radius:22px;padding:32px;box-shadow:0 16px 54px rgba(40,55,42,.07);text-align:start}.card h2{font-size:22px;margin:0 0 10px}.intro{font-size:14px;color:#6b7770;line-height:1.9;margin:0 0 25px}.step{padding:18px 0;border-top:1px solid #eeeee7;position:relative}.step strong{display:block;font-size:15px;margin-bottom:6px}.step small{display:block;color:#7b827c;line-height:1.8;font-size:12px}.tag{float:left;font-size:12px;line-height:23px;color:#8a928b;padding:0 8px;border-radius:12px;background:#f4f5ef}html[dir=ltr] .tag{float:right}.active{color:#21644e;background:#e9f3ed}.complete{color:#21644e;background:#e9f3ed}.track{height:7px;background:#e9ede7;border-radius:6px;overflow:hidden;margin:23px 0 12px}.fill{height:100%;width:0;background:#367456;border-radius:6px;transition:width .25s}.indeterminate .fill{width:30%!important;animation:sweep 1.7s infinite linear;-webkit-animation:sweep 1.7s infinite linear}@keyframes sweep{from{transform:translateX(-100%)}to{transform:translateX(350%)}}@-webkit-keyframes sweep{from{-webkit-transform:translateX(-100%)}to{-webkit-transform:translateX(350%)}}.status{font-size:13px;color:#557060;line-height:1.9;min-height:24px}.detail{font-size:12px;color:#81877f;line-height:1.8;word-wrap:break-word;margin-top:6px}.percent{font-size:12px;color:#8c784d;float:left}html[dir=ltr] .percent{float:right}.actions{margin-top:24px;text-align:center}.primary,.secondary,.quiet{border:0;border-radius:10px;padding:12px 24px}.primary{background:#245f49;color:#fff}.secondary{background:#eff2eb;color:#385344;margin:5px}.quiet{background:transparent;color:#758176;padding:8px;font-size:12px}.footer{color:#8c9187;font-size:11px;line-height:1.9;margin:22px 0}.error{color:#a44535}.errors{background:#fff5f1;border:1px solid #f1d9cf;padding:14px;border-radius:10px;margin:15px 0;word-wrap:break-word;text-align:start;white-space:pre-wrap;font-size:12px;line-height:1.7}.overlay{position:fixed;top:0;bottom:0;left:0;right:0;background:rgba(29,48,39,.28);z-index:5;text-align:center;overflow:auto;padding:12vh 18px}.dialog{max-width:450px;margin:0 auto;background:#fffdf8;border:1px solid #e6dfcb;border-radius:22px;padding:30px;box-shadow:0 24px 100px rgba(20,40,28,.2)}.dialog h2{font-size:21px;line-height:1.7;margin:0 0 13px}.dialog p{color:#778076;font-size:13px;line-height:1.9}.dialog-logo{width:80px;height:80px;margin-bottom:12px}.choices{margin-top:22px}.choices button{width:44%;margin:0 2%;padding:15px 6px}.hidden{display:none!important}@media(max-width:500px){body{padding:23px 12px}.card{padding:24px 20px}.logo{width:90px;height:90px}.brand{font-size:25px}.overlay{padding-top:8vh}}
</style></head><body>
<main class="shell"><img class="logo" src="/__startup/logo.png" alt="Noon / نون"><h1 class="brand">نُون <span dir="ltr">NOON</span></h1><p class="eyebrow" id="edition">تجهيز التطبيق</p>
<section class="card" aria-labelledby="heading"><h2 id="heading">مرحباً بك</h2><p class="intro" id="intro">نتحقق من بيانات التطبيق وفهارس البحث قبل البدء.</p>
<div class="step"><span id="databaseTag" class="tag">انتظار</span><strong id="databaseTitle">بيانات التطبيق</strong><small id="databaseHint">التحقق من قواعد البيانات المثبتة</small></div>
<div class="step"><span id="indexTag" class="tag">انتظار</span><strong id="indexTitle">فهارس البحث</strong><small id="indexHint">تحديث الفهارس الموجودة مع الاحتفاظ ببياناتك</small></div>
<div id="progress" class="track" role="progressbar" aria-label="Startup progress" aria-valuemin="0" aria-valuemax="100"><div id="fill" class="fill"></div></div>
<span id="percent" class="percent"></span><div id="status" class="status" role="status" aria-live="polite">اختر اللغة للبدء</div><div id="detail" class="detail"></div>
<div id="errors" class="errors hidden" role="alert"></div>
<div class="actions"><button id="retry" class="primary hidden" type="button">إعادة المحاولة</button><button id="open" class="primary hidden" type="button">فتح التطبيق</button><button id="skip" class="secondary hidden" type="button">الدخول دون تحديث</button><br><button id="cancel" class="quiet hidden" type="button">إيقاف التحديث</button></div>
</section><p class="footer" id="footer">جميع الحقوق محفوظة لمنتديات البشرى الإسلامية</p></main>
<div id="languageDialog" class="overlay hidden"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="languageTitle"><img class="dialog-logo" src="/__startup/logo.png" alt=""><h2 id="languageTitle"><span dir="rtl">اختر لغة التطبيق</span><br><span dir="ltr">Choose app language</span></h2><p><span dir="rtl">سنجهّز التطبيق ثم نفتح الصفحة الرئيسية.</span><br><span dir="ltr">We will prepare the app, then open its home page.</span></p><div class="choices"><button id="arabic" class="primary" type="button" lang="ar">العربية</button><button id="english" class="secondary" type="button" lang="en">English</button></div></section></div>
<script>
(function(){'use strict';
var lang='ar',timer=null,home='/',opening=false;
var words={ar:{edition:'تجهيز التطبيق',heading:'نجهّز لك نون',intro:'نتحقق من بيانات التطبيق ونحدّث فهارس البحث الموجودة، ثم نفتح التطبيق تلقائياً.',databaseTitle:'بيانات التطبيق',databaseHint:'التحقق من قواعد البيانات المثبتة',indexTitle:'فهارس البحث',indexHint:'مزامنة الفهارس الموجودة مع البيانات الحالية',footer:'جميع الحقوق محفوظة لمنتديات البشرى الإسلامية',retry:'إعادة المحاولة',open:'فتح التطبيق',skip:'الدخول دون تحديث',cancel:'إيقاف التحديث',waiting:'انتظار',working:'جارٍ العمل',done:'تم',choose:'اختر اللغة للبدء',checking:'نتحقق من بيانات التطبيق…',updating:'جارٍ تحديث فهارس البحث…',ready:'اكتمل التجهيز. جارٍ فتح التطبيق…',failed:'تعذّر إكمال التجهيز',stopped:'تم إيقاف التحديث',connection:'تعذّر الاتصال بالخادم المحلي. أعد المحاولة.',invalidresponse:'أعاد الخادم استجابة غير متوقعة.',timeout:'استغرق رد الخادم وقتاً طويلاً. أعد المحاولة.',noIndexes:'لا توجد فهارس سابقة لتحديثها. يمكنك إنشاء الفهارس من داخل التطبيق.',skipped:'الفهارس محدّثة؛ تم تجاوز البيانات التي لم تتغيّر.',forms:'المنتديات: ',checkdb:'التحقق من قواعد البيانات',sync:'مزامنة فهارس البحث',invalid:'تعذّر التحقق',notupdated:'لم يكتمل التحديث'},en:{edition:'PREPARING YOUR APP',heading:'Getting Noon ready',intro:'We check your app data and synchronize existing search indexes, then open the app automatically.',databaseTitle:'Application data',databaseHint:'Check the installed SQLite databases',indexTitle:'Search indexes',indexHint:'Synchronize existing indexes with current data',footer:'All rights reserved to Al-Bushra Islamic Forums.',retry:'Try again',open:'Open app',skip:'Open without updating',cancel:'Stop update',waiting:'Waiting',working:'In progress',done:'Done',choose:'Choose a language to begin',checking:'Checking application data…',updating:'Updating search indexes…',ready:'All ready. Opening your app…',failed:'Preparation could not finish',stopped:'Update stopped',connection:'Cannot reach the local server. Please try again.',invalidresponse:'The server returned an unexpected response.',timeout:'The server request timed out. Please retry.',noIndexes:'No existing indexes to update. You can create indexes inside the app.',skipped:'Indexes are current; unchanged data was skipped.',forms:'Forums: ',checkdb:'Checking databases',sync:'Synchronizing search indexes',invalid:'Check failed',notupdated:'Update incomplete'}};
function el(id){return document.getElementById(id);}function text(id,value){el(id).textContent=value;}function show(id,on){el(id).className=el(id).className.replace(/\\s*hidden/g,'')+(on?'':' hidden');}function w(key){return words[lang][key];}
function language(value){lang=value==='en'?'en':'ar';document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';var keys=['edition','heading','intro','databaseTitle','databaseHint','indexTitle','indexHint','footer','retry','open','skip','cancel'];for(var i=0;i<keys.length;i++)text(keys[i],w(keys[i]));text('databaseTag',w('waiting'));text('indexTag',w('waiting'));text('status',w('choose'));}
function request(path,method,done){var xhr=new XMLHttpRequest();var completed=false;function finish(data,error,fatal){if(completed)return;completed=true;done(data,error,fatal);}xhr.open(method,path,true);xhr.timeout=30000;xhr.onreadystatechange=function(){if(xhr.readyState!==4||xhr.status===0)return;var data;try{data=JSON.parse(xhr.responseText);}catch(e){finish(null,xhr.status? w('invalidresponse')+' (HTTP '+xhr.status+')':w('connection'),false);return;}if(xhr.status<200||xhr.status>=300){finish(null,data.error||w('invalidresponse'),data.fatal===true);return;}finish(data);};xhr.onerror=function(){finish(null,w('connection'),false);};xhr.ontimeout=function(){finish(null,w('timeout'),false);};xhr.send(null);}
function fail(message,fatal){clearTimeout(timer);el('progress').className='track';text('status',w('failed'));el('status').className='status error';text('errors',message||w('connection'));show('errors',true);show('retry',true);show('skip',!fatal);show('open',false);show('cancel',false);text('indexTag',w('notupdated'));}

function tag(id,key,kind){text(id,w(key));el(id).className='tag '+(kind||'');}
function detail(s){var value=s.message||'';if(lang==='ar'){if(value.indexOf('Database unchanged')>=0)return w('skipped');if(value.indexOf('Checking')===0)return w('checkdb');if(value.indexOf('Building ')===0)return w('sync')+' — '+(s.forms||'');if(value==='Lucene indexes built'||value==='Ready')return ''; }return value;}
function openApp(){if(opening)return;opening=true;location.replace(home);}
function render(s,error,fatal){if(!s){fail(error,fatal);return;}home=s.home||'/';var busy=s.phase==='running';show('errors',false);el('status').className='status';show('retry',false);show('skip',false);show('open',false);show('cancel',busy);var p=Math.max(0,Math.min(100,Number(s.percent)||0));el('fill').style.width=p+'%';el('progress').setAttribute('aria-valuenow',p);el('progress').className='track'+(busy&&p===0?' indeterminate':'');text('percent',busy&&p>0?p+'%':'');text('detail',detail(s));tag('databaseTag',s.checking_databases?'working':s.databases_checked?'done':'waiting',s.checking_databases?'active':s.databases_checked?'complete':'');tag('indexTag',busy?'working':'waiting',busy?'active':'');
 if(s.phase==='failed'||s.phase==='stopped'){fail(s.error||w('stopped'));if(!s.databases_checked)tag('databaseTag','invalid','error');return;}
 if(s.phase==='done'){tag('databaseTag','done','complete');tag('indexTag','done','complete');text('status',w('ready'));text('detail',s.no_indexes?w('noIndexes'):detail(s));el('fill').style.width='100%';show('open',true);show('cancel',false);timer=setTimeout(openApp,1100);return;}
 if(busy){text('status',w(s.checking_databases?'checking':'updating'));timer=setTimeout(poll,350);return;}
 text('status',w('checking'));timer=setTimeout(poll,350);
}
function poll(){request('/__startup/status','GET',render);}
function begin(){clearTimeout(timer);opening=false;show('errors',false);show('retry',false);show('skip',false);text('status',w('checking'));el('progress').className='track indeterminate';request('/__startup/start','POST',render);}
function choose(value){language(value);try{localStorage.setItem('welcome_language',lang);localStorage.setItem('welcome_language_user_selected','1');}catch(e){}show('languageDialog',false);begin();}
document.addEventListener('keydown',function(e){if(e.keyCode===9&&el('languageDialog').className.indexOf('hidden')<0){e.preventDefault();el(document.activeElement===el('arabic')?'english':'arabic').focus();}},false);el('arabic').onclick=function(){choose('ar');};el('english').onclick=function(){choose('en');};el('retry').onclick=begin;el('open').onclick=openApp;el('cancel').onclick=function(){el('cancel').disabled=true;request('/__lucene/stop','POST',function(){el('cancel').disabled=false;clearTimeout(timer);poll();});};el('skip').onclick=function(){request('/__startup/continue','POST',function(s,error,fatal){if(!s){fail(error,fatal);return;}home=s.home;openApp();});};
var savedLanguage=null;try{savedLanguage=localStorage.getItem('welcome_language');}catch(e){}if(savedLanguage==='ar'||savedLanguage==='en'){choose(savedLanguage);}else{language('ar');show('languageDialog',true);el('arabic').focus();}
})();
</script><script src="/__noon/context.js"></script></body></html>

""";
}
